extern void as_mysql_convert_possible ( mysql_conn_t * mysql_conn ) { ( void ) _set_db_curr_ver ( mysql_conn ) ; if ( db_curr_ver == NO_VAL ) { MYSQL_RES * result = NULL ; char * query = xstrdup_printf ( "select name from %s limit 1" , cluster_table ) ; DB_DEBUG ( DB_QUERY , mysql_conn -> conn , "query\n%s" , query ) ; if ( ( result = mysql_db_query_ret ( mysql_conn , query , 0 ) ) ) { mysql_free_result ( result ) ; fatal ( "Database schema is too old for this version of Slurm to upgrade." ) ; } xfree ( query ) ; debug4 ( "Database is new, conversion is not required" ) ; } if ( db_curr_ver < MIN_CONVERT_VERSION ) { fatal ( "Database schema is too old for this version of Slurm to upgrade." ) ; } if ( db_curr_ver > CONVERT_VERSION ) { char * err_msg = "Database schema is from a newer version of Slurm, downgrading is not possible." ; fatal ( "%s" , err_msg ) ; debug ( "%s" , err_msg ) ; } } 